<?php
use Illuminate\\Support\\Facades\\Route;use App\\Http\\Controllers\\{HomeController,ProductController,CartController,CheckoutController,AuthController,AccountController,AdminController};
Route::get('/',[HomeController::class,'index'])->name('home');Route::get('/produits',[ProductController::class,'index'])->name('products.index');Route::get('/produits/{product:slug}',[ProductController::class,'show'])->name('products.show');Route::get('/categorie/{category:slug}',[ProductController::class,'category'])->name('categories.show');
Route::get('/panier',[CartController::class,'index'])->name('cart.index');Route::post('/panier/ajouter/{product}',[CartController::class,'add'])->name('cart.add');Route::patch('/panier/{product}',[CartController::class,'update'])->name('cart.update');Route::delete('/panier/{product}',[CartController::class,'remove'])->name('cart.remove');Route::post('/devise',[CartController::class,'currency'])->name('currency');
Route::middleware('guest')->group(function(){Route::get('/connexion',[AuthController::class,'loginForm'])->name('login');Route::post('/connexion',[AuthController::class,'login'])->name('login.store');Route::get('/inscription',[AuthController::class,'registerForm'])->name('register');Route::post('/inscription',[AuthController::class,'register'])->name('register.store');});Route::post('/deconnexion',[AuthController::class,'logout'])->middleware('auth')->name('logout');
Route::middleware('auth')->group(function(){Route::get('/commande',[CheckoutController::class,'create'])->name('checkout');Route::post('/commande',[CheckoutController::class,'store'])->name('checkout.store');Route::get('/mon-compte',[AccountController::class,'index'])->name('account');Route::get('/mes-commandes',[AccountController::class,'orders'])->name('account.orders');Route::get('/mes-commandes/{order}',[AccountController::class,'order'])->name('account.order');Route::post('/favoris/{product}',[AccountController::class,'favorite'])->name('favorites.toggle');Route::post('/avis/{product}',[AccountController::class,'review'])->name('reviews.store');});
Route::prefix('admin')->name('admin.')->middleware(['auth','admin'])->group(function(){Route::get('/',[AdminController::class,'dashboard'])->name('dashboard');Route::get('/produits',[AdminController::class,'products'])->name('products');Route::post('/produits',[AdminController::class,'storeProduct'])->name('products.store');Route::delete('/produits/{product}',[AdminController::class,'deleteProduct'])->name('products.delete');Route::get('/commandes',[AdminController::class,'orders'])->name('orders');Route::patch('/commandes/{order}',[AdminController::class,'updateOrder'])->name('orders.update');});
